import { ComponentProps, useEffect } from 'react';

import { Paragraph } from 'components/UI';
import { useTruncationDetection } from 'hooks/useTruncationDetection';

interface TextWithDynamicTruncationProps extends ComponentProps<
  typeof Paragraph
> {
  children: string;
  shouldTruncate?: boolean;
  Component?: React.ElementType;
  dataTestId?: string;
  onTruncationChange?: (isTruncated: boolean) => void;
}

export const TextDynamicTruncation: React.FC<
  TextWithDynamicTruncationProps
> = ({
  children,
  shouldTruncate = true,
  Component = Paragraph,
  dataTestId,
  onTruncationChange,
  ...rest
}) => {
  const { ref, isTruncated } = useTruncationDetection<HTMLParagraphElement>(
    children,
    { enabled: shouldTruncate },
  );

  useEffect(() => {
    onTruncationChange?.(isTruncated);
  }, [isTruncated, onTruncationChange]);

  const hasTruncationTooltip = shouldTruncate && isTruncated;

  return (
    <Component
      {...rest}
      ref={shouldTruncate ? ref : undefined}
      title={hasTruncationTooltip ? children : undefined}
      data-testid={dataTestId}
      style={{
        display: 'block',
        textOverflow: shouldTruncate ? 'ellipsis' : 'clip',
        maxWidth: shouldTruncate ? '100%' : 'auto',
        overflow: shouldTruncate ? 'hidden' : 'visible',
        whiteSpace: shouldTruncate ? 'nowrap' : 'normal',
        ...(hasTruncationTooltip ? { cursor: 'pointer' } : {}),
      }}
    >
      {children}
    </Component>
  );
};
